// syncSearchFilterToken shows the `r` filter as an active token in the bar, and
// removes it when the filter is off. The table has no configured tokens, so the
// token only makes the bar visible and labels it; rows are prefiltered above.
func (b *RegistryBrowser) syncSearchFilterToken() {
	if b.searchFilter.isEmpty() {
		b.searchTable.FilterBar().SetTokens(nil)
		return
	}
	b.searchTable.FilterBar().SetTokens([]components.FilterToken{{Label: b.filterLabel(b.searchFilter), Active: true}})
}

// searchFilterStops returns the stops `r` cycles through on level 1: the
// lot's registries, in form order, that have at least one image row.
func (b *RegistryBrowser) searchFilterStops() []resultFilter {
	has := make(map[string]bool, len(b.images))
	for _, img := range b.images {
		has[img.EntryKey] = true
	}
	var keys []string
	for _, k := range b.searchKeys {
		if has[k] {
			keys = append(keys, k)
		}
	}
	return b.filterStopsFor(keys)
}

// cycleSearchRegistryFilter advances `r` on level 1; the cursor follows its
// row through rebuildSearchTable.
func (b *RegistryBrowser) cycleSearchRegistryFilter() {
	b.searchFilter = nextFilter(b.searchFilterStops(), b.searchFilter)
	b.rebuildSearchTable()
}

// reselect puts the cursor back on the row prev, by (EntryKey, Repo) and not by
// index: rows of another registry land before or after it, and a sort moves it.
// Without a previous selection the cursor goes to the first row; a vanished row
// leaves the cursor where it is.
func (b *RegistryBrowser) reselect(prev searchRow, had bool) {
	if !had {
		b.searchTable.GotoTop()
		return
	}
	for i, r := range b.searchTable.Visible() {
		if r.img.EntryKey == prev.img.EntryKey && r.img.Repo == prev.img.Repo {
			b.searchTable.SetCursor(i)
			return
		}
	}
}

// cycleSearchSort advances the level 1 sort (`.`); the cursor follows the row
// it was on (DEVDESK-309).
func (b *RegistryBrowser) cycleSearchSort() {
	prev, had := b.searchTable.Selected()
	b.searchTable.CycleSort()
	b.reselect(prev, had)
}

// AddImageResults takes one registry's answer. It returns false, touching
// nothing, when the answer belongs to another lot. pendingSearches never goes
// below zero.
func (b *RegistryBrowser) AddImageResults(msg ImageSearchResultMsg) bool {
	if msg.Gen != b.gen {
		return false
	}
	if b.pendingSearches > 0 {
		b.pendingSearches--
	}
	oc := imagesearch.Classify(msg.Err, len(msg.Images), msg.Partial)
	if b.outcomes == nil {
		b.outcomes = map[string]imagesearch.Outcome{}
	}
	b.outcomes[msg.EntryKey] = oc
	if oc.Verdict == imagesearch.VerdictOK {
		for _, img := range msg.Images {
			img.EntryKey = msg.EntryKey
			b.images = append(b.images, img)
		}
	}
	b.rebuildSearchTable()
	return true
}

// handleImagesKeyMsg handles the keys of the level 1 table. left goes straight
// back to the form; esc acts in order: the filter bar while it is open, then a
// confirmed query, then it cancels the lot and goes back to the form (which
// keeps the typed name and the selection). The lot's late answers are no
// longer wanted and are dropped
// (TestEscAtLevelOneCancelsTheLotAndIgnoresItsLateAnswers). enter does
// nothing: a row has no action yet; → opens the row's tags.
func (b *RegistryBrowser) handleImagesKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
	if b.searchTable.InEditMode() {
		return b, b.searchTable.Update(msg)
	}
	switch msg.String() {
	case ".":
		b.cycleSearchSort()
		return b, nil
	case "r":
		b.cycleSearchRegistryFilter()
		return b, nil
	case "right":
		return b.openSelectedImageTags()
	case "esc":
		if bar := b.searchTable.FilterBar(); bar.SearchQuery() != "" {
			// The cursor stays on the selected row once the filter is gone.
			prev, had := b.searchTable.Selected()
			bar.ClearSearch()
			b.searchTable.SetItems(b.searchTable.Items())
			b.reselect(prev, had)
			return b, nil
		}
		return b.backToForm()
	case "left":
		return b.backToForm()
	case "enter":
		return b, nil
	}
	return b, b.searchTable.Update(msg)
}

// backToForm cancels the lot and returns to the form, which keeps the typed
// name and the selection. Late answers of the lot are dropped.
func (b *RegistryBrowser) backToForm() (*RegistryBrowser, tea.Cmd) {
// countMembers returns how many entries belong to a group.
func countMembers(entries []browserRegistryEntry, slug string) int {
	n := 0
	for _, e := range entries {
		if e.ParentSlug == slug {
			n++
		}
	}
	return n
}

func (b *RegistryBrowser) cycleRegistryFilter() {
	b.registryFilter = nextFilter(b.filterStops(), b.registryFilter)
	b.rebuildTagTable()
}

// nextFilter returns the stop after cur: off goes to the first stop, the last
// stop and any unknown filter go back to off.
func nextFilter(stops []resultFilter, cur resultFilter) resultFilter {
	if len(stops) == 0 {
		return resultFilter{}
	}
	if cur.isEmpty() {
		return stops[0]
	}
	for i, s := range stops {
		if s == cur {
			if i+1 < len(stops) {
				return stops[i+1]
			}
			return resultFilter{}
		}
	}
	return resultFilter{}
}

// entryFor returns the browser entry a result came from, or nil.
//
// It resolves by entry key, not by URL: every member of a path-routed group
// answers to the same host, so a URL identifies a whole instance and a result
// would be unattributable (§3.18, and D40 one screen along).
func (b *RegistryBrowser) entryFor(key string) *browserRegistryEntry {
	for i := range b.entries {
		if b.entries[i].key == key {
			return &b.entries[i]
		}
	}
	return nil
}

// registryFilterLabel returns a short display label for the active filter.
package ociresources

import (
	"slices"
	"strings"
	"testing"

	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/imagesearch"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// DEVDESK-310 (IS-06) step 5: `r` on level 1 narrows the image list to one
// group or one registry. Black box: keys in, rows, header, footer and bar out.
// The `r` shortcut entry and the help text belong to step 6, not tested here.

const (
	rfWidth = 180
	rfDesc  = "Bitnami packaged"
)

var (
	rfM1  = memberKey("prod", "registry.example.com", "docker-hosted")
	rfM2  = memberKey("prod", "registry.example.com", "dhi-proxy")
	rfHub = "hub"
)

// rfSearchModel starts a level 1 search over the group prod (members m1, m2)
// and the lone registry hub, in that form order. No answer has arrived yet.
func rfSearchModel(t *testing.T) (Model, *fakeSearcher) {
	t.Helper()
	fake := &fakeSearcher{}
	withImageSearcher(t, fake)
	return searchLot(t, groupedModel(t)), fake
}

func rfImage(name, desc string) []imagesearch.Image {
	return []imagesearch.Image{{Name: name, Repo: name, Description: desc}}
}

// rfAnswered has m1 "nginx", m2 "redis" and hub "nginx-hub" in the table.
func rfAnswered(t *testing.T) (Model, *fakeSearcher) {
	t.Helper()
	m, fake := rfSearchModel(t)
	m = answerFor(t, m, rfM1, rfImage("nginx", ""), false, nil)
	m = answerFor(t, m, rfM2, rfImage("redis", ""), false, nil)
	m = answerFor(t, m, rfHub, rfImage("nginx-hub", ""), false, nil)
	if m.registryBrowser.pendingSearches != 0 {
		t.Fatalf("fixture: pendingSearches = %d", m.registryBrowser.pendingSearches)
	}
	return m, fake
}

func rfNames(m Model) []string {
	names := lvl1Names(m)
	slices.Sort(names)
	return names
}

func rfWantNames(t *testing.T, m Model, want ...string) {
	t.Helper()
	slices.Sort(want)
	if got := rfNames(m); !slices.Equal(got, want) {
		t.Fatalf("rows = %q, want %q", got, want)
	}
}

func rfBar(m Model) string { return ansi.Strip(m.registryBrowser.FilterBarView(rfWidth)) }

// AC2: `r` goes through the group, each registry, then off.
func TestRCyclesTheGroupEachRegistryThenOffOnLevelOne(t *testing.T) {
	m, _ := rfAnswered(t)
	b := m.registryBrowser
	if m.GetFooterHeight() != 2 {
		t.Fatalf("fixture: footer height = %d, want 2", m.GetFooterHeight())
	}

	steps := []struct {
		label string
		rows  []string
	}{
		{b.filterLabel(resultFilter{groupSlug: "prod"}), []string{"nginx", "redis"}},
		{b.filterLabel(resultFilter{entryKey: rfM1}), []string{"nginx"}},
		{b.filterLabel(resultFilter{entryKey: rfM2}), []string{"redis"}},
		{b.filterLabel(resultFilter{entryKey: rfHub}), []string{"nginx-hub"}},
	}
	for i, s := range steps {
		m = feed(t, m, testutil.Key("r"))
		rfWantNames(t, m, s.rows...)
		if !b.FilterIsVisible() {
			t.Errorf("stop %d: the bar is hidden", i)
		}
		if !strings.Contains(rfBar(m), "["+s.label+"]") && !strings.Contains(rfBar(m), s.label) {
			t.Errorf("stop %d: token %q missing in the bar %q", i, s.label, rfBar(m))
		}
		if got := m.GetFooterHeight(); got != 4 {
			t.Errorf("stop %d: footer height = %d, want 4", i, got)
		}
		if got := lvl1Header(t, m, "Images"); got != itoa(len(s.rows)) {
			t.Errorf("stop %d: Images = %q, want %d", i, got, len(s.rows))
		}
	}
	m = feed(t, m, testutil.Key("r"))
	rfWantNames(t, m, "nginx", "redis", "nginx-hub")
	if b.FilterIsVisible() {
		t.Error("off: the bar is still visible")
	}
	if got := m.GetFooterHeight(); got != 2 {
		t.Errorf("off: footer height = %d, want 2", got)
	}
}

func itoa(n int) string { return string(rune('0' + n)) }

// The cursor follows its row through the narrowing.
func TestRKeepsTheCursorOnTheSameImage(t *testing.T) {
	m, _ := rfAnswered(t)
	b := m.registryBrowser
	b.searchTable.SetCursor(slices.IndexFunc(b.searchTable.Visible(), func(r searchRow) bool { return r.img.Name == "redis" }))
	assertSelected(t, b, rfM2, "redis")
	m = feed(t, m, testutil.Key("r")) // group prod
	assertSelected(t, m.registryBrowser, rfM2, "redis")
}

// AC3: one registry with rows (the other found nothing): nothing to narrow to.
func TestRDoesNothingWithASingleRegistryHoldingRows(t *testing.T) {
	withImageSearcher(t, &fakeSearcher{})
	m := registryModel(t, anonymousRegistry("docker.io", "hub"), anonymousRegistry("dhi.io", "dhi.io"))
	m = searchLot(t, m)
	m = answerFor(t, m, "hub", rfImage("nginx", ""), false, nil)
	m = answerFor(t, m, "dhi.io", nil, false, nil)
	m = feed(t, m, testutil.Key("r"))
	rfWantNames(t, m, "nginx")
	if m.registryBrowser.FilterIsVisible() {
		t.Error("the bar is visible with a single stop")
	}
	if got := m.GetFooterHeight(); got != 2 {
		t.Errorf("footer height = %d, want 2", got)
	}
}

// AC1: `/` still searches the description, and never asks a registry again.
func TestSlashStillMatchesTheDescriptionAndDoesNotSearchAgain(t *testing.T) {
	m, fake := rfSearchModel(t)
	m = answerFor(t, m, rfM1, rfImage("web", rfDesc), false, nil)
	m = answerFor(t, m, rfM2, rfImage("redis", "key value"), false, nil)
	m = answerFor(t, m, rfHub, rfImage("other", ""), false, nil)
	calls := fake.calls()
	m = feed(t, m, testutil.Key("/"))
	m = feed(t, m, testutil.Type("bit")...)
	m = feed(t, m, testutil.Key("enter"))
	rfWantNames(t, m, "web")
	if got := fake.calls(); got != calls {
		t.Errorf("searcher calls = %d after the filter, want %d", got, calls)
	}
}

// AC5: r, . and : typed in the open bar go to the field.
func TestRDotAndColonTypedInTheOpenBarGoToTheField(t *testing.T) {
	m, _ := rfAnswered(t)
	b := m.registryBrowser
	m = feed(t, m, testutil.Key("r")) // group prod
	m = feed(t, m, testutil.Key("/"))
	m = feed(t, m, testutil.Type("r.:")...)
	if !b.searchTable.InEditMode() {
		t.Fatal("the bar closed")
	}
	if got := b.searchTable.FilterBar().SearchQuery(); got != "r.:" && !strings.Contains(rfBar(m), "r.:") {
		t.Errorf("the field does not hold r.: (%q)", rfBar(m))
	}
	if col, desc := b.searchTable.SortState(); col != -1 || desc {
		t.Errorf("SortState = (%d,%v): the dot sorted", col, desc)
	}
	if label := b.filterLabel(resultFilter{groupSlug: "prod"}); !strings.Contains(rfBar(m), label) {
		t.Errorf("the r token %q left the bar: %q", label, rfBar(m))
	}
	m = feed(t, m, testutil.Key("esc"))
	b = m.registryBrowser
	if b.state != browserStateImages || b.searchTable.InEditMode() {
		t.Fatalf("esc: state %d, edit mode %v", b.state, b.searchTable.InEditMode())
	}
	if !b.FilterIsVisible() {
		t.Error("esc dropped the r filter")
	}
}

// AC6: nothing left after r and a query: a header-only table, still full width.
func TestRWithAQueryThatKeepsNothingLeavesAHeaderOnlyTable(t *testing.T) {
	m, _ := rfAnswered(t)
	m = feed(t, m, testutil.Key("r"))
	m = feed(t, m, testutil.Key("/"))
	m = feed(t, m, testutil.Type("zzz")...)
	m = feed(t, m, testutil.Key("enter"))
	b := m.registryBrowser
	if got := len(b.searchTable.Visible()); got != 0 {
		t.Fatalf("%d rows, want 0", got)
	}
	if got := lvl1Header(t, m, "Images"); got != "0" {
		t.Errorf("Images = %q, want 0", got)
	}
	if got, want := b.searchTable.RenderedWidth(), rfWidth-2; got != want {
		t.Errorf("RenderedWidth = %d, want %d", got, want)
	}
}

// r and / combine with AND, in either order.
func TestRAndSlashCombine(t *testing.T) {
	m, _ := rfAnswered(t)
	m = feed(t, m, testutil.Key("r")) // group prod: nginx, redis
	m = feed(t, m, testutil.Key("/"))
	m = feed(t, m, testutil.Type("nginx")...)
	m = feed(t, m, testutil.Key("enter"))
	rfWantNames(t, m, "nginx")
	m = feed(t, m, testutil.Key("r")) // m1: still nginx
	rfWantNames(t, m, "nginx")
	m = feed(t, m, testutil.Key("r")) // m2 holds redis, which the query drops
	rfWantNames(t, m)
	m = feed(t, m, testutil.Key("r")) // hub
	rfWantNames(t, m, "nginx-hub")
	m = feed(t, m, testutil.Key("r")) // off: the query alone
	rfWantNames(t, m, "nginx", "nginx-hub")
}

// While the search runs, a filtered registry's rows stay out, the stops grow
// with the registries that answer, and the cursor stays.
func TestRDuringTheSearchHidesFilteredRowsAndGrowsTheStops(t *testing.T) {
	m, _ := rfSearchModel(t)
	m = answerFor(t, m, rfM1, rfImage("nginx", ""), false, nil)
	m = answerFor(t, m, rfHub, rfImage("nginx-hub", ""), false, nil)
	m = feed(t, m, testutil.Key("r")) // stops so far: prod, m1, hub
	m = feed(t, m, testutil.Key("r")) // m1
	rfWantNames(t, m, "nginx")
	b := m.registryBrowser
	assertSelected(t, b, rfM1, "nginx")

	m = answerFor(t, m, rfM2, rfImage("redis", ""), false, nil)
	rfWantNames(t, m, "nginx")
	assertSelected(t, b, rfM1, "nginx")

	m = feed(t, m, testutil.Key("r")) // the new stop m2 now follows m1
	rfWantNames(t, m, "redis")
}

// right and left keep the r filter and its token.
func TestRSurvivesTagsAndBack(t *testing.T) {
	withTagRecorder(t)
	m, _ := rfAnswered(t)
	m = feed(t, m, testutil.Key("r")) // group prod
	m = feed(t, m, testutil.Key("right"))
	if m.registryBrowser.state != browserStateTags {
		t.Fatalf("state = %d, want tags", m.registryBrowser.state)
	}
	m = feed(t, m, testutil.Key("left"))
	if m.registryBrowser.state != browserStateImages {
		t.Fatalf("state = %d, want images", m.registryBrowser.state)
	}
	rfWantNames(t, m, "nginx", "redis")
	if !m.registryBrowser.FilterIsVisible() {
		t.Error("the r token is gone after tags and back")
	}
}

// A new search clears the r filter and its token (Q2).
func TestANewSearchClearsTheRFilter(t *testing.T) {
	m, _ := rfAnswered(t)
	m = feed(t, m, testutil.Key("r"))
	m = feed(t, m, testutil.Key("left")) // back to the form
	m, _ = submitRaw(t, m, "nginx")
	b := m.registryBrowser
	if b.state != browserStateImages {
		t.Fatalf("state = %d, want images", b.state)
	}
	if b.FilterIsVisible() {
		t.Error("the r token survived a new search")
	}
	m = answerFor(t, m, rfM1, rfImage("nginx", ""), false, nil)
	m = answerFor(t, m, rfM2, rfImage("redis", ""), false, nil)
	m = answerFor(t, m, rfHub, rfImage("nginx-hub", ""), false, nil)
	rfWantNames(t, m, "nginx", "redis", "nginx-hub")
}
	if got := next.registryBrowser.searchTable.Cursor(); got != cursor {
		t.Errorf("cursor = %d, want %d", got, cursor)
	}
	if got := lvl1Names(next); !slices.Equal(got, names) {
		t.Errorf("rows = %v, want %v", got, names)
	}
	if next.footer.IsSet() {
		t.Errorf("enter set a footer message: %q", next.footer.Text())
	}
	if next.confirmModal != nil || next.scanAllModal != nil {
		t.Error("enter opened a modal")
	}
}

// c.7, c.8, Rules 130 and 137: the shortcuts of level 1.
func TestLevelOneShortcuts(t *testing.T) {
	m := lvl1ImagesModel(t)
	sc := m.GetShortcuts()
	for _, key := range []string{"→", "/", ".", "esc"} {
		if !testutil.HasShortcut(sc, key) {
			t.Errorf("level 1 lacks the %q shortcut", key)
		}
		if testutil.HasShortcut(sc, key) && !testutil.ShortcutEnabled(sc, key) {
			t.Errorf("%q is greyed at level 1", key)
		}
	}
	for _, key := range []string{"enter", "r"} {
		if testutil.HasShortcut(sc, key) {
			t.Errorf("level 1 advertises %q", key)
		}
	}

	if got, want := testutil.ShortcutKeys(sc), []string{"→", "/", ".", "esc"}; !slices.Equal(got, want) {
		t.Errorf("level 1 keys = %v, want %v (Sort between / and esc)", got, want)
	}
	if !slices.ContainsFunc(sc, func(s shortcut.Shortcut) bool { return s.Key == "." && s.Description == "Sort" }) {
		t.Error(`level 1 lacks {Key: ".", Description: "Sort"}`)
	}

	m = feed(t, m, testutil.Key("/"))
	sc = m.GetShortcuts()
	if !testutil.HasShortcut(sc, "enter/esc") {
		t.Errorf("no enter/esc Close filter while typing: %v", testutil.ShortcutKeys(sc))
	}
}

// Rule 130: the set of keys does not depend on whether there are rows.
func TestLevelOneShortcutKeysDoNotDependOnTheRows(t *testing.T) {
	empty := lvl1SearchingModel(t)
	filled := lvl1ImagesModel(t)
	a := testutil.ShortcutKeys(empty.GetShortcuts())
	b := testutil.ShortcutKeys(filled.GetShortcuts())
	if !slices.Equal(a, b) {
		t.Errorf("keys without rows = %v, with rows = %v", a, b)
	}
}

// Level 2 keeps its enter.
